SELECT mcpgwcl.*, sac.name AS assemble_config_name, mbp.id AS process_id, mbp.name AS process_name, sas.spec_prefix AS assemble_spec_prefix FROM mes_contract_project_group_welding_config_link mcpgwcl LEFT JOIN sys_assemble_config sac ON sac.id = mcpgwcl.assemble_config_id LEFT JOIN sys_assemble_spec sas ON sas.bool_delete_enum = FALSE AND sas.assemble_config_id = mcpgwcl.assemble_config_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mcpgwcl.process) > 0 WHERE mcpgwcl.bool_delete_enum = FALSE
AND mcpgwcl.contract_project_id in (
#{i}
)

SELECT mcpgwcl.*, sac.name AS assemble_config_name, mbp.id AS process_id, mbp.name AS process_name, sas.spec_prefix AS assemble_spec_prefix FROM mes_contract_project_group_welding_config_link mcpgwcl LEFT JOIN sys_assemble_config sac ON sac.id = mcpgwcl.assemble_config_id LEFT JOIN sys_assemble_spec sas ON sas.bool_delete_enum = FALSE AND sas.assemble_config_id = mcpgwcl.assemble_config_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mcpgwcl.process) > 0 WHERE mcpgwcl.bool_delete_enum = FALSE
AND mcpgwcl.id in (
#{i}
)

SELECT mcpgwcl.*, sac.name AS assemble_config_name, mbp.id AS process_id, mbp.name AS process_name, sas.spec_prefix AS assemble_spec_prefix FROM mes_contract_project_group_welding_config_link mcpgwcl LEFT JOIN sys_assemble_config sac ON sac.id = mcpgwcl.assemble_config_id LEFT JOIN sys_assemble_spec sas ON sas.bool_delete_enum = FALSE AND sas.assemble_config_id = mcpgwcl.assemble_config_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mcpgwcl.process) > 0 WHERE mcpgwcl.bool_delete_enum = FALSE
AND mcpgwcl.contract_project_id = #{param.projectId}
AND mcpgwcl.assemble_config_id = #{param.assembleConfigId}
AND FIND_IN_SET(#{param.processId}, mcpgwcl.process) > 0
